        assert(b as int == ((n as int) / 100) % 10);
        assert(c as int == ((n as int) / 10) % 10);
        assert(d as int == (n as int) % 10);

        // Relate int arithmetic to nat arithmetic via the cast (since n>=0).
        assert((n as int) / 1000 == n_nat / 1000);
        assert(((n as int) / 100) % 10 == (n_nat / 100) % 10);
        assert(((n as int) / 10) % 10 == (n_nat / 10) % 10);
        assert((n as int) % 10 == n_nat % 10);

        // Therefore, the tuple of digits matches the spec.
        assert(digits4(n_nat) == (a as nat, b as nat, c as nat, d as nat));

